            const dmMatch = content.match(dmRegex);

            if (scMatch) {
                scContentHtml += `<span class="sc-ticker-item"><span class="sc-item-static">文本44</span><span class="sc-item-name">${scMatch[2]}</span><span class="sc-item-static">文本45</span><span class="sc-item-amount">${scMatch[1]}</span><span class="sc-item-static">:</span><span class="sc-item-message">${scMatch[3]}</span></span>`;
